package repository

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/routeguard/api/internal/domain"
)

// AuditRepo handles audit log writes and reads.
type AuditRepo struct {
	pool *pgxpool.Pool
}

// NewAuditRepo creates a new AuditRepo.
func NewAuditRepo(pool *pgxpool.Pool) *AuditRepo {
	return &AuditRepo{pool: pool}
}

// Log writes an audit_log entry. The ID is generated by the database DEFAULT.
// This method is non-blocking in intent; callers may ignore the returned error.
func (r *AuditRepo) Log(ctx context.Context, entry domain.AuditLog) error {
	_, err := r.pool.Exec(ctx, `
		INSERT INTO audit_logs (
			id, actor_id, actor_type, action,
			target_type, target_id, metadata, ip_address
		) VALUES (
			gen_random_uuid(), $1, $2, $3,
			$4, $5, $6, $7
		)
	`,
		entry.ActorID, entry.ActorType, entry.Action,
		entry.TargetType, entry.TargetID, entry.Metadata, entry.IPAddress,
	)
	if err != nil {
		return fmt.Errorf("audit log: %w", err)
	}
	return nil
}

// List returns audit logs for an organization with pagination (limit/offset).
// Results are ordered newest-first.
func (r *AuditRepo) List(ctx context.Context, orgID string, limit, offset int) ([]domain.AuditLog, error) {
	if limit <= 0 {
		limit = 50
	}
	rows, err := r.pool.Query(ctx, `
		SELECT id, actor_id, actor_type, action,
		       target_type, target_id, metadata, ip_address, created_at
		FROM audit_logs
		WHERE org_id = $1
		ORDER BY created_at DESC
		LIMIT $2 OFFSET $3
	`, orgID, limit, offset)
	if err != nil {
		return nil, fmt.Errorf("audit list: %w", err)
	}
	defer rows.Close()

	logs := make([]domain.AuditLog, 0)
	for rows.Next() {
		var l domain.AuditLog
		if err := rows.Scan(
			&l.ID, &l.ActorID, &l.ActorType, &l.Action,
			&l.TargetType, &l.TargetID, &l.Metadata, &l.IPAddress, &l.CreatedAt,
		); err != nil {
			return nil, err
		}
		logs = append(logs, l)
	}
	return logs, rows.Err()
}
